import { tags } from "typia";

import { IShoppingAttributeValue } from "./IShoppingAttributeValue";

/**
 * Represents a variant attribute value for a SKU (e.g., color: Red, size: L).
 * Maps to a row in the shopping_sku_variants table. Used for composition in the
 * SKU detail view.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingSkuVariant = {
  /** Variant assignment PK. */
  id: string & tags.Format<"uuid">;

  /** FK to attribute value (color, size, etc). */
  shopping_attribute_value_id: string & tags.Format<"uuid">;

  /** Order in variant attribute array (0-based). */
  order_index: number & tags.Type<"int32">;

  /** The attribute value (summary: code, value, dimension). */
  attribute_value: IShoppingAttributeValue;
};
